import React, { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import styles from "../../app/page.module.css";
import axios from "axios";
import secureLocalStorage from "react-secure-storage";
import fs from "fs";
// Ajout pour la génération PDF côté serveur
import PDFDocument from "pdfkit";
import blobStream from "blob-stream";

export default function ReportsList({
  reports = [],
}: {
  reports: {
    type: string;
    label: string;
    period: string;
    data: {
      totalSteps: number;
      totalDistance: number;
      totalRevenue: number;
      growth: string;
      daily: { date: string; steps: number; distance: number; revenue: number }[];
    };
    influenceHistory?: { date: string; count: number }[];
    chartImage?: string;
    influenceChartImage?: string;
    topUsersChartImage?: string;
    companyName?: string;
  }[];
}) {
  const [companyName, setCompanyName] = useState<string>("");

  useEffect(() => {
    const fetchCompany = async () => {
      try {
        const userToken = secureLocalStorage.getItem("userToken") as string | null;
        if (!userToken) return;

        const userInfoResponse = await axios.get(
          `${process.env.NEXT_PUBLIC_AUTH0_DOMAIN}/userinfo`,
          {
            headers: {
              Authorization: `Bearer ${userToken}`,
              "Content-Type": "application/json",
            },
          }
        );
        const userId = userInfoResponse.data.sub;

        const response = await axios.get(
          `${process.env.NEXT_PUBLIC_AUTH0_DOMAIN}/api/v2/users/${userId}`,
          {
            headers: {
              Authorization: `Bearer ${userToken}`,
              "Content-Type": "application/json",
            },
          }
        );
        const denomination = response.data?.user_metadata?.denomination?.trim();
        setCompanyName(denomination || "");
      } catch (error) {
        setCompanyName("");
      }
    };

    fetchCompany();
  }, []);

  // Fonction pour générer le PDF côté serveur
  function generateServerPDF(report: any) {
    const doc = new PDFDocument();
    const stream = blobStream();

    doc.pipe(stream);

    doc.fontSize(25).text(`Rapport ${report.label}`, { align: "center" });
    doc.moveDown();
    doc.fontSize(16).text(`Entreprise : ${report.companyName || "Non renseignée"}`);
    doc.text(`Période : ${report.period || "Non renseignée"}`);
    doc.text(`Total Steps : ${report.data.totalSteps || 0}`);
    doc.text(`Total Distance : ${report.data.totalDistance || 0}`);
    doc.text(`Total Revenue : ${report.data.totalRevenue || 0}`);
    doc.text(`Croissance : ${report.data.growth || "0 %"}`);
    doc.moveDown();
    doc.fontSize(14).text("Données journalières :");
    report.data.daily.forEach((day: any) => {
      doc.text(
        `${day.date} - Pas: ${day.steps}, Distance: ${day.distance}, Revenu: ${day.revenue}`
      );
    });

    doc.end();

    return new Promise<Blob>((resolve) => {
      stream.on("finish", function () {
        resolve(stream.toBlob("application/pdf"));
      });
    });
  }

  // Fonction pour télécharger le PDF généré côté serveur
  const handleDownload = async (report: any) => {
    const blob = await generateServerPDF(report);
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `vyft-program-report-${report.type}-${report.period}.pdf`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    window.URL.revokeObjectURL(url);
  };

  return (
    <section
      className={styles.bodyonwhite}
      style={{
        background: "#fff",
        borderRadius: 24,
        padding: 32,
        marginBottom: 32,
        width: "100%",
        maxWidth: 700,
        boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
      }}
    >
      <h2 className={styles.headeronwhite} style={{ fontSize: 22, marginBottom: 18 }}>
        Liste des rapports générés
      </h2>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {reports.map((report, idx) => (
          <li
            key={idx}
            className={styles.bodyonwhite}
            style={{
              marginBottom: 18,
              background: "#DBDFE0",
              borderRadius: 18,
              padding: 18,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              {/* Titre */}
              <h3
                className={styles.headeronwhite}
                style={{
                  fontSize: 20,
                  margin: 0,
                  fontWeight: "bold",
                  color: "#1a7f6b",
                }}
              >
                Rapport {report.label}
              </h3>
              {/* Sous-titre */}
              <p
                className={styles.headeronwhite}
                style={{
                  fontSize: 15,
                  margin: "4px 0 0 0",
                  fontWeight: 500,
                  color: "#444444",
                }}
              >
                Période : {report.period}
              </p>
              {/* Corps */}
              <p
                className={styles.bodyonwhite}
                style={{
                  fontSize: 14,
                  margin: "4px 0 0 0",
                  color: "#222",
                }}
              >
                <b>Entreprise :</b> {report.companyName || companyName}
              </p>
            </div>
            <button
              onClick={() => handleDownload(report)}
              style={{
                background: "#1a7f6b",
                border: "none",
                cursor: "pointer",
                padding: 0,
                marginLeft: 12,
                borderRadius: 8,
                width: 44,
                height: 44,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
              }}
            >
              <img src="/nav_down.png" alt="Télécharger PDF" style={{ width: 28, height: 28 }} />
            </button>
          </li>
        ))}
      </ul>
    </section>
  );
}